using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Microsoft.UI.Xaml;using UPM.Windows.Core;using UPM.Windows.SiteApi;using UPM.Windows.Transfers;
namespace UPM.SiteManager;
public partial class App:Application{readonly IHost host;public App(){InitializeComponent();host=Host.CreateDefaultBuilder().ConfigureServices(s=>{var root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"UPM","SiteManager");s.AddSingleton<ICredentialVault,CredentialVault>();s.AddSingleton(new LocalStateStore(Path.Combine(root,"state.db")));s.AddHttpClient<SiteApiClient>().ConfigurePrimaryHttpMessageHandler(()=>new HttpClientHandler{UseCookies=true,CookieContainer=new()});s.AddSingleton<TransferWorker>();s.AddHostedService(p=>p.GetRequiredService<TransferWorker>());s.AddSingleton<MainWindow>();}).Build();}protected override async void OnLaunched(LaunchActivatedEventArgs args){await host.Services.GetRequiredService<LocalStateStore>().InitializeAsync();await host.StartAsync();host.Services.GetRequiredService<MainWindow>().Activate();}}
